function eventMatches(){
 if(r.statusCode!==200||b?.id!==c.eventId||b?.status!=='confirmed'||b.attendeesOmitted===true)return false;
 if(b.extendedProperties?.private?.n8nCandidateId!==c.candidateId||b.extendedProperties?.private?.n8nInterviewType!==c.type)return false;
