 const actual=[...new Set(b.attendees.map(a=>a.email.toLowerCase()))].sort();return JSON.stringify(actual)===JSON.stringify([...c.attendees].sort());
}
if(r.statusCode===404){if(c.stage===c.type+'_booking'&&c.claimExpired)return fail('BOOKING_REVIEW_REQUIRED');if(c.stage===c.type+'_scheduled')return fail('BOOKING_CHANGED');return [{json:{eventExists:false}}];}
if(r.statusCode===410||b?.status==='cancelled')return fail('BOOKING_CHANGED');
if(r.statusCode!==200)return fail('PROVIDER_ERROR');
if(![c.type+'_booking',c.type+'_scheduled'].includes(c.stage)||!eventMatches())return fail('BOOKING_CHANGED');
return [{json:{eventExists:true,recordVersion:c.recordVersion,alreadyBooked:true}}];

