for(const id of c.calendars){const calendar=b.calendars[id];if(!calendar||!Array.isArray(calendar.busy)||(calendar.errors!==undefined&&(!Array.isArray(calendar.errors)||calendar.errors.length>0)))return fail('AVAILABILITY_INCOMPLETE');
